using LibreKO.Editors.Contracts;
using LibreKO.Editors.Core.Events;
using LibreKO.Editors.DataHost.Events;
using System.Text.Json.Nodes;
public class EventSchemaTests {
 [Theory][InlineData("NaN")][InlineData("Infinity")][InlineData("-Infinity")]
 public void CoordinatesMustBeFinite(string value){var values=(JsonObject)EventSchema.Catalog().Tables.Single(t=>t.Table==EventTable.MapObjects).Defaults.DeepClone();values["Id"]=1;values["X"]=value;var change=new EventChange(Guid.NewGuid(),new(new(EventFamily.MapObject,1),[],"missing"),[new(new(EventTable.MapObjects,1),null,values)]);Assert.Contains(EventRules.Validate(change,EventSchema.Catalog()),i=>i.Field.EndsWith(".X"));}
 [Fact] public void SnapshotsUseNumericEnumsAndExcludeLiveSiegeStateFromVersion(){var row=EventSchema.Snapshot(EventTable.TempleEventSchedules,new LibreKO.Common.Domain.Entities.GameData.TempleEventScheduleData{Id=1,Event=LibreKO.Common.Enums.TempleEvent.Chaos});Assert.Equal(1,row.Values["Event"]!.GetValue<int>());var siege=new LibreKO.Common.Domain.Entities.GameData.SiegeWarfareData{CastleIndex=1,WarDay=1};var original=EventSchema.Snapshot(EventTable.SiegeWarfare,siege);siege.MasterKnights=321;siege.MoradonTax=500;Assert.Equal(original.Version,EventSchema.Snapshot(EventTable.SiegeWarfare,siege).Version);siege.WarDay=2;Assert.NotEqual(original.Version,EventSchema.Snapshot(EventTable.SiegeWarfare,siege).Version);}
 [Fact] public void EveryTableHasWhitelistedFieldsAndSiegeStateIsProtected(){var catalog=EventSchema.Catalog();Assert.Equal(14,catalog.Tables.Count);var siege=catalog.Tables.Single(t=>t.Table==EventTable.SiegeWarfare);Assert.False(siege.Fields.Single(f=>f.Field.Name=="MasterKnights").Field.Writable);Assert.False(siege.Fields.Single(f=>f.Field.Name=="MoradonTax").Field.Writable);Assert.True(siege.Fields.Single(f=>f.Field.Name=="WarDay").Field.Writable);Assert.Equal("Trap number",catalog.Tables.Single(t=>t.Table==EventTable.EventTriggers).Fields.Single(f=>f.Field.Name=="NpcId").Label);}
 [Theory][InlineData("Hour",24)][InlineData("Minute",60)] public void InvalidScheduleTimeIsRejected(string field,int value){var key=new EventRowKey(EventTable.TempleEventSchedules,1);var after=new JsonObject{["Id"]=1,["Event"]=1,["Day"]=null,["Hour"]=0,["Minute"]=0,["MinLevel"]=0,["MaxLevel"]=0,["CountdownMinutes"]=0};after[field]=value;var change=new EventChange(Guid.NewGuid(),new(new(EventFamily.Temple,1),[],"v"),[new(key,null,after)]);Assert.NotEmpty(EventRules.Validate(change,EventSchema.Catalog()));}
 [Fact] public void ExistingUnknownEnumSurvivesUnrelatedEditButNewTempleModeIsRejected(){var key=new EventRowKey(EventTable.TempleEventSchedules,1);var values=EventFixture.Row(EventTable.TempleEventSchedules,1);values["Event"]=99;values["Hour"]=1;var before=new EventRowSnapshot(key,(JsonObject)values.DeepClone(),"v");values["Hour"]=2;var existing=new EventChange(Guid.NewGuid(),new(new(EventFamily.Temple,99),[before],"v"),[new(key,before,values)]);Assert.Empty(EventRules.Validate(existing,EventSchema.Catalog()));Assert.NotEmpty(EventRules.Validate(existing with{Before=new(new(EventFamily.Temple,99),[],"missing"),Rows=[new(key,null,values)]},EventSchema.Catalog()));}
 [Fact] public void InvalidProbabilityLongNameNegativeCountAndParentMismatchAreRejected(){var catalog=EventSchema.Catalog();EventChange Change(EventTable table,JsonObject values)=>new(Guid.NewGuid(),new(new(EventFamily.CollectionRace,1),[],"missing"),[new(new(table,1),null,values)]);Assert.NotEmpty(EventRules.Validate(Change(EventTable.CollectionRaceRewards,new(){["Id"]=1,["RaceId"]=1,["ItemId"]=1,["ItemCount"]=1,["Rate"]=101}),catalog));Assert.NotEmpty(EventRules.Validate(Change(EventTable.CollectionRaceObjectives,new(){["Id"]=1,["RaceId"]=2,["Ordinal"]=0,["Kind"]=0,["TargetId"]=1,["Count"]=-1}),catalog));Assert.NotEmpty(EventRules.Validate(Change(EventTable.CollectionRaces,new(){["Id"]=1,["Name"]=new string('x',129)}),catalog));}
}
